 "content": "def transform(grid):
    # Each connected marker block of one color is a filled rectangle in a
    # reduced output matrix. The original grid's repeated separator lines are
    # the lattice; marker pairs at the rectangle corners indicate block extent.
    from collections import deque
    markers = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v not in (5, 9):
                markers.setdefault(v, []).append((r, c))
    # The lattice has 5-row by 7-column cells; map each marker crossing to
    # its row/column interval, expanding matching corner pairs across the block.
    out = [[5 for _ in range(4)] for _ in range(4)]
    for color, pts in markers.items():
        cells = set()
        for r,c in pts:
            ri = max(0, min(3, (r - 2) // 5))
            ci = max(0, min(3, c // 7))
            cells.add((ri,ci))
        if len(cells) >= 2:
            r0=min(r for r,c in cells); r1=max(r for r,c in cells)
            c0=min(c for r,c in cells); c1=max(c for r,c in cells)
            # marker pair pattern at rectangle corners fills the enclosed region
            if len(cells) >= 4 or (r0==r1 and c1-c0>=1) or (c0==c1 and r1-r0>=1):
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1): out[r][c]=color
    return out
